CREATE TABLE "tblOutboxMessage"
(
    "Id"            BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "EventId"       UUID                                    NOT NULL,
    "EventType"     VARCHAR(100)                            NOT NULL,
    "Payload"       JSONB                                   NOT NULL,
    "CreatedAt"     TIMESTAMP WITH TIME ZONE                NOT NULL,
    "NextAttemptAt" TIMESTAMP WITH TIME ZONE                NOT NULL,
    "Attempts"      INTEGER                                 NOT NULL DEFAULT 0,

    CONSTRAINT "PK_OutboxMessage" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_OutboxMessage_EventId" UNIQUE ("EventId")
);

CREATE INDEX "IX_OutboxMessage_NextAttemptAtId" ON "tblOutboxMessage" ("NextAttemptAt", "Id");
